import { createHash, randomUUID } from 'node:crypto';
import {
  lstat,
  open,
  readdir,
  readFile,
  realpath,
  mkdir,
  writeFile,
  rename,
  unlink,
} from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import homeManifest from '../resources/example-catalog/home-manifest.json' with { type: 'json' };

// Host build tooling only. Hash a conservative dependency closure, including
// generated bytes and pinned assets; timestamps never establish a cache hit.
const defaultPaths = [
  'api',
  'context',
  'core',
  'electron',
  'lib',
  'scripts',
  'server',
  'schemas',
  'examples',
  'resources/example-catalog',
  'tests/fixtures/reference',
  'resources/example-models-lock.json',
  'resources/emc-flyback-models-lock.json',
  'resources/reference-models-lock.json',
  'public/licenses/ti-models.txt',
  'package.json',
  'package-lock.json',
  'tsconfig.json',
  'node_modules/.package-lock.json',
];
const defaultOutputs = [
  'resources/example-catalog/simulation',
  ...[...homeManifest.recent, ...homeManifest.examples].flatMap(({ file }) => [
    `examples/${file}/3D`,
    `examples/${file}/circuits`,
    `examples/${file}/circuit`,
    `examples/${file}/models`,
  ]),
  'schemas/internal-project-snapshot.schema.json',
  'lib/project-validator.mjs',
  'lib/project-document-validator.mjs',
  'server/example-models-lock.mjs',
  ...[
    'simulation-model',
    'appearance',
    'project',
    'library',
    'spice',
    'thermal',
    'model-cad',
    'ti',
    'workspace',
    'agent-provider',
    'annotation',
    'agent-context',
  ].flatMap((name) => [`server/${name}-format.mjs`, `server/${name}-format.d.mts`]),
];
// Generated solver records belong to the saved project, not Home preparation.
const resultDirectories = [...homeManifest.recent, ...homeManifest.examples].flatMap(({ file }) => [
  `examples/${file}/spice`,
  `examples/${file}/thermal`,
]);
const workspace = fileURLToPath(new URL('../', import.meta.url));
const missing = (error) => error.code === 'ENOENT';
const normalized = (value) => (process.platform === 'win32' ? value.toLowerCase() : value);

function contained(root, relative) {
  const absolute = path.resolve(root, relative);
  const local = path.relative(root, absolute);
  if (!local || local.startsWith('..') || path.isAbsolute(local))
    throw new Error('Invalid development preparation cache path.');
  return absolute;
}

async function inspect(root, relative, createParents = false) {
  const target = contained(root, relative);
  const parts = path.relative(root, target).split(path.sep);
  let current = root;
  for (let index = 0; index < parts.length; index++) {
    current = path.join(current, parts[index]);
    const parent = index < parts.length - 1;
    if (parent && createParents)
      await mkdir(current).catch((error) => {
        if (error.code !== 'EEXIST') throw error;
      });
    const info = await lstat(current).catch((error) => {
      if (missing(error)) return null;
      throw error;
    });
    if (!info) return null;
    if (info.isSymbolicLink() || (parent && !info.isDirectory()))
      throw new Error('Development preparation cache paths cannot contain links.');
    if (!parent) return info;
  }
}

const sameInput = (a, b) =>
  a.dev === b.dev &&
  a.ino === b.ino &&
  a.size === b.size &&
  a.mtimeMs === b.mtimeMs &&
  a.ctimeMs === b.ctimeMs;

async function inputHash(root, relative, expected) {
  const target = contained(root, relative);
  const changed = () =>
    new Error(
      `Development preparation input changed while being read: ${relative}. Retry startup.`,
    );
  const handle = await open(target, 'r');
  try {
    if (!sameInput(await handle.stat(), expected)) throw changed();
    const hash = createHash('sha256');
    let size = 0;
    for await (const chunk of handle.createReadStream({
      highWaterMark: 256 * 1024,
      autoClose: false,
    })) {
      hash.update(chunk);
      size += chunk.length;
    }
    const after = await lstat(target);
    if (
      size !== expected.size ||
      after.isSymbolicLink() ||
      !sameInput(after, expected) ||
      !sameInput(await handle.stat(), expected)
    )
      throw changed();
    return hash.digest('hex');
  } finally {
    await handle.close();
  }
}

async function snapshot(root, paths, outputs) {
  const entries = [];
  const files = [];
  async function visit(relative, checkedParent = false) {
    const local = normalized(relative.replaceAll('\\', '/'));
    if (
      resultDirectories.some(
        (directory) =>
          local === normalized(directory) || local.startsWith(normalized(directory) + '/'),
      )
    )
      return;
    const info = checkedParent
      ? await lstat(contained(root, relative))
      : await inspect(root, relative);
    if (!info) {
      entries.push([relative, 'missing']);
      return;
    }
    if (info.isSymbolicLink()) throw new Error('Development preparation inputs cannot be links.');
    if (info.isDirectory()) {
      entries.push([relative, 'directory']);
      const children = await readdir(contained(root, relative));
      for (const child of children.sort()) {
        if (child === '.git' || child.endsWith('.tmp')) continue;
        await visit(`${relative}/${child}`, true);
      }
    } else if (info.isFile()) {
      const entry = [relative, null];
      entries.push(entry);
      files.push({ entry, info });
    } else throw new Error('Development preparation inputs must be regular files.');
  }
  for (const relative of [...paths].sort()) await visit(relative);
  let next = 0;
  let failed = false;
  let failure;
  // Retain traversal order in the fingerprint while bounding open handles and
  // streaming buffers. A failed read drains active jobs before permitting retry.
  await Promise.all(
    Array.from({ length: Math.min(4, files.length) }, async () => {
      while (!failed && next < files.length) {
        const { entry, info } = files[next++];
        try {
          entry[1] = await inputHash(root, entry[0], info);
        } catch (error) {
          if (!failed) {
            failed = true;
            failure = error;
          }
        }
      }
    }),
  );
  if (failed) throw failure;
  const identity = JSON.stringify([root, process.version, process.platform, process.arch]);
  const hash = (items) =>
    createHash('sha256').update(identity).update(JSON.stringify(items)).digest('hex');
  return {
    all: hash(entries),
    inputs: hash(
      entries.filter(
        ([file]) =>
          !outputs.some((output) => file === output || file.startsWith(`${output}/`)) &&
          ![...homeManifest.recent, ...homeManifest.examples].some((entry) =>
            ['3D', 'footprints'].some(
              (folder) =>
                file.startsWith(`examples/${entry.file}/${folder}/`) &&
                /^[^/]+\.step$/i.test(file.slice(`examples/${entry.file}/${folder}/`.length)),
            ),
          ),
      ),
    ),
  };
}

export async function withDevPreparationCache({
  root = workspace,
  logger,
  prepare,
  cancelled = () => false,
  paths = defaultPaths,
  outputs = defaultOutputs,
  cacheFile = '.openpe/dev-preparation-v1.json',
}) {
  root = path.resolve(root);
  const rootInfo = await lstat(root);
  if (
    !rootInfo.isDirectory() ||
    rootInfo.isSymbolicLink() ||
    normalized(await realpath(root)) !== normalized(root)
  )
    throw new Error('Development preparation requires a regular workspace directory.');
  const before = await snapshot(root, paths, outputs);
  let saved;
  try {
    const info = await inspect(root, cacheFile);
    if (info?.isFile() && info.size < 4096)
      saved = JSON.parse(await readFile(contained(root, cacheFile), 'utf8'));
  } catch (error) {
    // An unreadable or malformed optimization record never replaces preparation.
    logger.error(`Development preparation cache unavailable: ${error.message}`);
  }
  if (!cancelled() && saved?.version === 1 && saved.fingerprint === before.all) {
    logger.status('Project formats and Home resources unchanged');
    return true;
  }
  if (cancelled()) return false;
  await prepare();
  if (cancelled()) return false;
  const after = await snapshot(root, paths, outputs);
  // A developer may edit a source while preparation runs. Such a run cannot
  // certify that its generated files reflect those new inputs.
  if (cancelled() || before.inputs !== after.inputs) return false;
  let temporary;
  try {
    const info = await inspect(root, cacheFile, true);
    if (info && !info.isFile()) throw new Error('Development cache must be a regular file.');
    const target = contained(root, cacheFile);
    temporary = `${target}.${randomUUID()}.tmp`;
    await writeFile(temporary, JSON.stringify({ version: 1, fingerprint: after.all }) + '\n', {
      flag: 'wx',
    });
    if (!cancelled()) await rename(temporary, target);
  } catch (error) {
    logger.error(`Could not retain development preparation cache: ${error.message}`);
  } finally {
    if (temporary)
      await unlink(temporary).catch((error) => {
        if (!missing(error))
          logger.error(`Could not remove development cache temporary file: ${error.message}`);
      });
  }
  return false;
}
